plt.suptitle('C1 — Renewable Energy Potential (1km² resolution)',
             fontsize=13, fontweight='bold')
plt.tight_layout()
plt.savefig('outputs/phase2/01_c1_renewable.png', dpi=200, bbox_inches='tight')
